from __future__ import annotations

import argparse
import json
import math
import sqlite3
from datetime import datetime
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse
from zoneinfo import ZoneInfo

BASE = Path(__file__).resolve().parents[1]
DB = BASE / "data" / "kwara.db"
LOTS = BASE / "config" / "lots.json"
TZ = ZoneInfo("America/Sao_Paulo")


def brl(v):
    if v is None:
        return "—"
    return f"R$ {float(v):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def parse_dt(v):
    if not v:
        return None
    try:
        return datetime.fromisoformat(v).astimezone(TZ)
    except Exception:
        return None


def iso_local(v):
    dt = parse_dt(v)
    return dt.isoformat() if dt else None


def fmt_dt(v):
    dt = parse_dt(v)
    return dt.strftime("%d/%m/%Y %H:%M:%S") if dt else "—"


def decision(next_bid, max_bid, increment):
    if next_bid is None or max_bid is None:
        return "SEM DADOS"
    nxt = float(next_bid)
    ceiling = float(max_bid)
    inc = 0.0 if increment is None else float(increment)
    if nxt > ceiling:
        return "ABANDONAR"
    if inc > 0 and (nxt + inc) > ceiling:
        return "ÚLTIMO LANCE"
    return "ATRATIVO"


def risk_band(pct, status):
    if status == "ABANDONAR":
        return "dead"
    if status == "ÚLTIMO LANCE":
        return "last"
    if pct is None:
        return "neutral"
    if pct < 0.90:
        return "good"
    if pct < 0.97:
        return "attention"
    return "last"


def bids_left(next_bid, max_bid, increment):
    if next_bid is None or max_bid is None:
        return 0
    nxt = float(next_bid)
    ceiling = float(max_bid)
    inc = 0.0 if increment is None else float(increment)
    if nxt > ceiling:
        return 0
    if inc <= 0:
        return 1
    return max(0, math.floor((ceiling - nxt) / inc) + 1)


def age_seconds(v):
    dt = parse_dt(v)
    if not dt:
        return None
    return max(0, int((datetime.now(TZ) - dt).total_seconds()))


def age_text(v):
    s = age_seconds(v)
    if s is None:
        return "—"
    if s < 60:
        return f"há {s}s"
    if s < 3600:
        return f"há {s // 60}min"
    return f"há {s // 3600}h {(s % 3600) // 60}min"


def fetch_rows(sql, params=()):
    con = sqlite3.connect(DB)
    con.row_factory = sqlite3.Row
    try:
        return [dict(r) for r in con.execute(sql, params).fetchall()]
    finally:
        con.close()


def fetch_one(sql, params=()):
    rows = fetch_rows(sql, params)
    return rows[0] if rows else None


def latest_snapshots():
    return fetch_rows(
        '''
        WITH ranked AS (
            SELECT s.*,
                   ROW_NUMBER() OVER (
                       PARTITION BY lot
                       ORDER BY captured_at DESC, id DESC
                   ) AS rn
            FROM snapshots s
        )
        SELECT * FROM ranked WHERE rn = 1
        '''
    )


def worker_status():
    return fetch_one("SELECT * FROM worker_status WHERE id=1") or {}


def previous_distinct_bid(lot, current):
    if current is None:
        return None
    rows = fetch_rows(
        '''
        SELECT next_bid, captured_at
        FROM snapshots
        WHERE lot=? AND parse_ok=1 AND next_bid IS NOT NULL
        ORDER BY id DESC
        LIMIT 200
        ''',
        (int(lot),),
    )
    current = float(current)
    for r in rows:
        v = r.get("next_bid")
        if v is not None and abs(float(v) - current) > 0.001:
            return float(v)
    return None


def history_for(lot):
    rows = fetch_rows(
        '''
        SELECT captured_at,current_value,next_bid,calculated_total,bid_count
        FROM snapshots
        WHERE lot=? AND parse_ok=1
        ORDER BY id
        ''',
        (int(lot),),
    )
    changes = []
    marker = object()
    prev_cur = marker
    prev_next = marker
    for r in rows:
        cur = r.get("current_value")
        nxt = r.get("next_bid")
        if cur != prev_cur or nxt != prev_next:
            changes.append(
                {
                    "time": fmt_dt(r.get("captured_at")),
                    "current": brl(cur),
                    "next": brl(nxt),
                    "cost": brl(r.get("calculated_total")),
                    "bids": int(r.get("bid_count") or 0),
                }
            )
        prev_cur, prev_next = cur, nxt
    return list(reversed(changes[-10:]))


def build_state():
    cfg_list = json.loads(LOTS.read_text(encoding="utf-8"))
    cfg = {int(x["lot"]): x for x in cfg_list}
    enabled = {lot for lot, c in cfg.items() if c.get("enabled", True)}

    lots = []
    for r in latest_snapshots():
        lot = int(r["lot"])
        if lot not in enabled:
            continue

        def f(name):
            v = r.get(name)
            return None if v is None else float(v)

        current = f("current_value")
        nxt = f("next_bid")
        cost = f("calculated_total")
        market = f("market_value")
        ceiling = f("max_bid")
        increment = f("increment") or 0.0
        cb = f("cb_index") or 0.0

        status = decision(nxt, ceiling, increment)
        pct = (nxt / ceiling) if nxt is not None and ceiling else None
        risk = risk_band(pct, status)
        margin = (market - cost) if market is not None and cost is not None else None
        headroom = (ceiling - nxt) if ceiling is not None and nxt is not None else None
        prev = previous_distinct_bid(lot, nxt)
        delta = (nxt - prev) if prev is not None and nxt is not None else None

        lots.append(
            {
                "lot": lot,
                "title": cfg.get(lot, {}).get("title", r.get("title", "")),
                "url": cfg.get(lot, {}).get("url", "#"),
                "current": current,
                "current_brl": brl(current),
                "next": nxt,
                "next_brl": brl(nxt),
                "cost": cost,
                "cost_brl": brl(cost),
                "market": market,
                "market_brl": brl(market),
                "ceiling": ceiling,
                "ceiling_brl": brl(ceiling),
                "increment": increment,
                "increment_brl": brl(increment),
                "margin": margin,
                "margin_brl": brl(margin),
                "headroom": headroom,
                "headroom_brl": brl(headroom),
                "pct": pct,
                "pct_text": "—" if pct is None else f"{pct*100:.1f}%",
                "bids_left": bids_left(nxt, ceiling, increment),
                "cb": cb,
                "cb_text": f"{cb:.2f}",
                "status": status,
                "risk": risk,
                "end_at": iso_local(r.get("end_at")),
                "end_text": fmt_dt(r.get("end_at")),
                "captured_at": r.get("captured_at"),
                "bid_count": int(r.get("bid_count") or 0),
                "delta": delta,
                "delta_text": (
                    "sem alteração registrada"
                    if delta is None or abs(delta) < 0.001
                    else f"{brl(prev)} → {brl(nxt)} (+{brl(abs(delta))})"
                ),
                "history": history_for(lot),
            }
        )

    rank = {"ATRATIVO": 0, "ÚLTIMO LANCE": 1, "ABANDONAR": 2, "SEM DADOS": 3}
    lots.sort(key=lambda x: (rank.get(x["status"], 9), -x["cb"]))

    ws = worker_status()
    captures = [x["captured_at"] for x in lots if x.get("captured_at")]
    latest_capture = max(captures) if captures else None

    now = datetime.now(TZ)
    end_values = [parse_dt(x["end_at"]) for x in lots if x.get("end_at")]
    end_values = [x for x in end_values if x and x > now]
    nearest = min(end_values).isoformat() if end_values else None

    failures = int(ws.get("failures") or 0)
    return {
        "generated_at": now.isoformat(),
        "latest_snapshot": latest_capture,
        "cycle_finished_at": ws.get("cycle_finished_at"),
        "successes": int(ws.get("successes") or 0),
        "enabled_lots": int(ws.get("enabled_lots") or 0),
        "failures": failures,
        "nearest_end": nearest,
        "online": (age_seconds(latest_capture) or 10**9) <= 420,
        "counts": {
            "total": len(lots),
            "attractive": sum(x["status"] == "ATRATIVO" for x in lots),
            "last": sum(x["status"] == "ÚLTIMO LANCE" for x in lots),
            "abandon": sum(x["status"] == "ABANDONAR" for x in lots),
            "failures": failures,
        },
        "lots": lots,
    }


